from ursina import Shader
MAX_LIGHTS = 8
LIT_VERTEX = '\n#version 140\nuniform mat4 p3d_ModelViewProjectionMatrix;\nuniform mat4 p3d_ModelMatrix;\nuniform mat4 p3d_TextureMatrix;     // texture_scale / texture_offset of an entity (welded meshes have it baked in)\nin vec4 p3d_Vertex;\nin vec3 p3d_Normal;\nin vec4 p3d_Color;\nin vec2 p3d_MultiTexCoord0;\n\nout vec3 world_pos;\nout vec3 world_normal;\nout vec4 vcolor;\nout vec2 uv;\n\nvoid main() {\n    gl_Position = p3d_ModelViewProjectionMatrix * p3d_Vertex;\n    world_pos = (p3d_ModelMatrix * p3d_Vertex).xyz;\n    world_normal = normalize(mat3(p3d_ModelMatrix) * p3d_Normal);\n    vcolor = p3d_Color;\n    uv = (p3d_TextureMatrix * vec4(p3d_MultiTexCoord0, 0.0, 1.0)).xy;\n}\n'
LIT_FRAGMENT = '\n#version 140\nuniform sampler2D p3d_Texture0;\nuniform vec4 p3d_ColorScale;\n\n// ---- scene-wide values, set once per scene by LightRig ----\nuniform vec3  ambient_color;\nuniform vec3  sun_dir;          // direction pointing TOWARD the sun/moon\nuniform vec3  sun_color;\nuniform vec3  light_pos[8];\nuniform vec3  light_col[8];     // colour * intensity\nuniform float light_rad[8];     // 0 = unused slot\nuniform vec3  cam_pos;\nuniform vec3  fog_color;\nuniform float fog_density;\n\n// ---- per-object value ----\nuniform float emissive;         // 0 = fully lit by lights, 1 = glows by itself\n\nin vec3 world_pos;\nin vec3 world_normal;\nin vec4 vcolor;\nin vec2 uv;\nout vec4 fragColor;\n\nvoid main() {\n    vec4 base = texture(p3d_Texture0, uv) * vcolor * p3d_ColorScale;\n    vec3 N = normalize(world_normal);\n\n    vec3 light = ambient_color;\n    light += sun_color * max(dot(N, normalize(sun_dir)), 0.0);\n\n    for (int i = 0; i < 8; i++) {\n        if (light_rad[i] <= 0.0) continue;\n        vec3 to_light = light_pos[i] - world_pos;\n        float dist = length(to_light);\n        float falloff = clamp(1.0 - dist / light_rad[i], 0.0, 1.0);\n        falloff = falloff * falloff;\n        float facing = max(dot(N, to_light / max(dist, 0.001)), 0.0);\n        // 0.35 + 0.65*facing = "wrapped" lighting so shadows side is not pitch black\n        light += light_col[i] * falloff * (0.35 + 0.65 * facing);\n    }\n\n    vec3 col = base.rgb * light;\n    col = mix(col, base.rgb * 1.15, emissive);\n\n    // soft highlight shoulder: linear below 0.7, then smoothly compressed toward 1.0\n    // (stops strongly-lit surfaces from clipping to flat white)\n    vec3 over = max(col - 0.7, 0.0);\n    col = min(col, vec3(0.7)) + 0.3 * (1.0 - exp(-over / 0.3));\n\n    // exponential-squared distance fog\n    float d = length(cam_pos - world_pos);\n    float fog = 1.0 - exp(-pow(d * fog_density, 2.0));\n    col = mix(col, fog_color, clamp(fog, 0.0, 1.0));\n\n    fragColor = vec4(col, base.a);\n}\n'
lit_shader = Shader(name='night_crow_lit_shader', language=Shader.GLSL, vertex=LIT_VERTEX, fragment=LIT_FRAGMENT, default_input={'emissive': 0.0})
POST_FRAGMENT = '\n#version 150\nuniform sampler2D tex;\nuniform float time;\nuniform float vignette;        // 0 = none, 1 = strong dark corners\nuniform float desat;           // 0 = full colour, 1 = black & white\nuniform float flash;           // 0..1 additive flash\nuniform float bloom;           // glow strength\nuniform float grain;           // film grain strength\nuniform float aberration;      // chromatic aberration strength\nuniform vec3  tint;            // multiply colour grade\nuniform vec3  flash_color;\nuniform float sight;           // 0..1 Crow Sight: blue-grey grade, brighter midtones, a pulse ring\n\nin vec2 uv;\nout vec4 color;\n\nfloat hash(vec2 p) {\n    return fract(sin(dot(p, vec2(12.9898, 78.233)) + time) * 43758.5453);\n}\n\nconst vec2 DIRS[8] = vec2[8](vec2(1.0, 0.0), vec2(0.7071, 0.7071), vec2(0.0, 1.0), vec2(-0.7071, 0.7071),\n                             vec2(-1.0, 0.0), vec2(-0.7071, -0.7071), vec2(0.0, -1.0), vec2(0.7071, -0.7071));\n\nvoid main() {\n    vec2 dir = uv - 0.5;\n    vec3 c;\n    c.r = texture(tex, uv + dir * aberration).r;\n    c.g = texture(tex, uv).g;\n    c.b = texture(tex, uv - dir * aberration).b;\n\n    // --- bloom: gather bright pixels from two rings around this pixel (16 taps; the outer ring is turned\n    //     22.5 degrees so its taps fall between the inner ones) ---\n    //     (skipped completely when bloom is 0: performance mode saves 16 texture reads per pixel)\n    if (bloom > 0.002) {\n        vec2 ts = 1.0 / vec2(textureSize(tex, 0));\n        vec3 glow = vec3(0.0);\n        for (int i = 0; i < 8; i++) {\n            vec2 o  = DIRS[i];\n            vec2 o2 = vec2(o.x * 0.9239 - o.y * 0.3827, o.x * 0.3827 + o.y * 0.9239);\n            glow += max(texture(tex, uv + o  * ts * 5.0).rgb  - 0.62, 0.0);\n            glow += max(texture(tex, uv + o2 * ts * 12.0).rgb - 0.62, 0.0) * 0.8;\n        }\n        c += glow * (bloom / 8.0);\n    }\n\n    // --- colour grade ---\n    c *= tint;\n    float lum = dot(c, vec3(0.299, 0.587, 0.114));\n    c = mix(c, vec3(lum), desat);\n\n    // --- Crow Sight: the world drains to blue-grey, shadows lift, a ring pulses outward from the centre ---\n    if (sight > 0.001) {\n        float l2 = dot(c, vec3(0.299, 0.587, 0.114));\n        vec3 eye = vec3(pow(l2, 0.72) * 1.35) * vec3(0.52, 0.82, 1.22);\n        float r = length(dir * vec2(1.7, 1.0));\n        float ring = smoothstep(0.045, 0.0, abs(r - fract(time * 0.35) * 0.9)) * (1.0 - fract(time * 0.35));\n        c = mix(c, eye + vec3(0.04, 0.10, 0.2) * ring, sight * 0.78);\n        c += vec3(0.1, 0.25, 0.5) * smoothstep(0.35, 0.85, r) * sight * 0.35;\n    }\n\n    // --- vignette ---\n    float v = smoothstep(0.85, 0.25, length(dir) * 1.15);\n    c *= mix(1.0, v, vignette);\n\n    // --- grain + flash ---\n    c += (hash(uv * 800.0) - 0.5) * grain;\n    c += flash_color * flash;\n\n    color = vec4(c, 1.0);\n}\n'
post_shader = Shader(name='night_crow_post_shader', language=Shader.GLSL, fragment=POST_FRAGMENT, default_input={'time': 0.0, 'vignette': 0.35, 'desat': 0.0, 'flash': 0.0, 'bloom': 0.55, 'grain': 0.035, 'aberration': 0.0006, 'tint': (1.0, 1.0, 1.0), 'flash_color': (1.0, 1.0, 1.0), 'sight': 0.0})
PARTICLE_VERTEX = '\n#version 140\nuniform mat4 p3d_ModelViewProjectionMatrix;\nuniform mat4 p3d_ModelMatrix;\nin vec4 p3d_Vertex;\nin vec4 p3d_Color;\nin vec2 p3d_MultiTexCoord0;\nout vec3 world_pos;\nout vec4 vcolor;\nout vec2 uv;\nvoid main() {\n    gl_Position = p3d_ModelViewProjectionMatrix * p3d_Vertex;\n    world_pos = (p3d_ModelMatrix * p3d_Vertex).xyz;\n    vcolor = p3d_Color;\n    uv = p3d_MultiTexCoord0;\n}\n'
PARTICLE_FRAGMENT = '\n#version 140\nuniform sampler2D p3d_Texture0;\nuniform vec3  cam_pos;\nuniform vec3  fog_color;\nuniform float fog_density;\nin vec3 world_pos;\nin vec4 vcolor;\nin vec2 uv;\nout vec4 fragColor;\nvoid main() {\n    vec4 c = texture(p3d_Texture0, uv) * vcolor;\n    float d = length(cam_pos - world_pos);\n    float fog = clamp(1.0 - exp(-pow(d * fog_density, 2.0)), 0.0, 1.0);\n    // distant particles fade into the fog instead of glowing through it\n    c.a *= 1.0 - fog * 0.85;\n    fragColor = c;\n}\n'
particle_shader = Shader(name='night_crow_particle_shader', language=Shader.GLSL, vertex=PARTICLE_VERTEX, fragment=PARTICLE_FRAGMENT, default_input={})
